from pathlib import Path
import re

home_path = Path('/home/ubuntu/devora-frontend/client/src/pages/Home.tsx')
text = home_path.read_text()

text = text.replace('import { useMemo, useState } from "react";', 'import { useEffect, useMemo, useState } from "react";')
text = text.replace('ArrowUpRight, BookOpen, BrainCircuit, Check, ChevronDown, ChevronRight, CircleHelp, Code2, FileText, Github, LayoutDashboard, LockKeyhole, LogOut, Menu, MessageSquare, MoreHorizontal, Network, Plus, Search, Server, Settings2, ShieldCheck, Sparkles, Upload, Users, X, Zap', 'ArrowUpRight, BookOpen, BrainCircuit, Check, ChevronDown, ChevronRight, CircleHelp, Code2, FileText, Github, LayoutDashboard, LockKeyhole, LogOut, Menu, MessageSquare, MoreHorizontal, Network, Search, Server, Settings2, ShieldCheck, Sparkles, Upload, Users, X, Zap')
text = text.replace('import { defaultSkillProfile, parseSkillProfile, personalizeModules, type SkillProfile } from "@/lib/devoraMockData";', 'import { analyzeAssessment, defaultSkillProfile, parseSkillProfile, personalizeModules, type SkillProfile } from "@/lib/devoraMockData";')
text = text.replace('type View = "dashboard" | "learning" | "documentation" | "notes" | "repository" | "members" | "twin" | "heatmap";', 'type View = "dashboard" | "learning" | "documentation" | "notes" | "repository" | "members" | "twin" | "heatmap" | "gap-review";')
text = text.replace('  const [assessmentComplete, setAssessmentComplete] = useState(false);', '  const [assessmentComplete, setAssessmentComplete] = useState(false);\n  const [notesUnread, setNotesUnread] = useState(true);')
text = text.replace('  const enter = (nextRole: Role) => { setRole(nextRole); setAuthenticated(true); setView("dashboard"); };\n  const logout = () => { setAuthenticated(false); setRole(null); setView("dashboard"); };', '  const enter = (nextRole: Role) => { setRole(nextRole); setAuthenticated(true); setView("dashboard"); };\n  const logout = () => { setAuthenticated(false); setRole(null); setView("dashboard"); };\n  useEffect(() => { window.scrollTo(0, 0); if (view === "notes") setNotesUnread(false); }, [view]);\n  const submitAssessment = (answers: Record<number, string>) => { const next = analyzeAssessment(answers); setTwinProfile((current) => ({ ...current, skills: next.scores })); setAssessmentComplete(true); setView("twin"); };')
text = text.replace('onClick={() => { setView(key); setMobileNav(false); }}><Icon size={17} /><span>{label}</span>{key === "notes" && <i className="unread-dot" />}', 'onClick={() => { setView(key); setMobileNav(false); }}><Icon size={17} /><span>{label}</span>{key === "notes" && notesUnread && <i className="unread-dot" />}')
text = text.replace('<Avatar initials={role === "admin" ? "MC" : "MC"} color="#8cf7d0" /><div><strong>{role === "admin" ? "Maya Chen" : "Maya Chen"}</strong>', '<Avatar initials={role === "admin" ? "TS" : "MC"} color="#8cf7d0" /><div><strong>{role === "admin" ? "Taylor Swift" : "Maya Chen"}</strong>')
text = text.replace('onHeatmap={() => setView("heatmap")} onAdminMember={setMemberFocus}', 'onHeatmap={() => setView("heatmap")} onGapReview={() => setView("gap-review")} onAdminMember={setMemberFocus}')
text = text.replace('<LearningPath onAssessment={() => setView("twin")} modulePlan={modulePlan}', '<LearningPath onAssessmentSubmit={submitAssessment} modulePlan={modulePlan}')
text = text.replace('{view === "twin" && <DeveloperTwin profile={twinProfile} assessmentComplete={assessmentComplete} onProfileUpdate={(profile) => { setTwinProfile(profile); setAssessmentComplete(true); }} onBack={() => setView("dashboard")} />}', '{view === "twin" && <DeveloperTwin profile={twinProfile} assessmentComplete={assessmentComplete} onLearningPath={() => setView("learning")} />}\n        {view === "gap-review" && <KnowledgeGapReview onBack={() => setView("dashboard")} />}')
text = text.replace('onProject={() => setShowProject(true)} onView={setView} onModule={() => setView("learning")}', 'onProject={() => setShowProject(true)} onView={setView} onModule={() => setView("learning")}', 1)
text = text.replace('<footer className="landing-footer"><span>Build less context. Make more progress.</span><span>CtrlAltElite · 2026</span></footer>', '<footer className="landing-footer"><span>CtrlAltElite · 2026</span></footer>')
text = text.replace('placeholder="Maya Chen"', 'placeholder={role === "admin" ? "Taylor Swift" : "Maya Chen"}')
text = text.replace('<span>YOUR MODULES</span>', '<span>LEARNING MAP</span>')

# Update Dashboard signature and admin wiring.
text = text.replace('function Dashboard({ role, modulePlan, title, onProject, onView, onModule, onTwin, onHeatmap, onAdminMember }: { role: Role; modulePlan: ReturnType<typeof personalizeModules>; title: string; onProject: () => void; onView: (view: View) => void; onModule: () => void; onTwin: () => void; onHeatmap: () => void; onAdminMember: (member: Member) => void }) {', 'function Dashboard({ role, modulePlan, title, onProject, onView, onModule, onTwin, onHeatmap, onGapReview, onAdminMember }: { role: Role; modulePlan: ReturnType<typeof personalizeModules>; title: string; onProject: () => void; onView: (view: View) => void; onModule: () => void; onTwin: () => void; onHeatmap: () => void; onGapReview: () => void; onAdminMember: (member: Member) => void }) {')
text = text.replace('<AdminDashboard onView={onView} onHeatmap={onHeatmap} onMember={onAdminMember} />', '<AdminDashboard onView={onView} onHeatmap={onHeatmap} onGapReview={onGapReview} onMember={onAdminMember} />')

# Replace the Admin dashboard with an interactive command deck and review-gaps CTA.
admin_pattern = r'function AdminDashboard\([\s\S]*?\n\nfunction LearningPath'
admin_replacement = '''function AdminDashboard({ onView, onHeatmap, onGapReview, onMember }: { onView: (view: View) => void; onHeatmap: () => void; onGapReview: () => void; onMember: (member: typeof members[number]) => void }) {
  return <div className="admin-dashboard"><section className="admin-overview"><div className="team-constellation"><div className="constellation-lines" /><div className="team-core"><Users size={22} /><strong>4</strong><small>Team Members</small></div>{members.map((member, index) => <button key={member.name} className={`constellation-member constellation-${index + 1}`} onClick={() => onMember(member)}><Avatar initials={member.initials} color={member.color} /><span>{member.name.split(" ")[0]}</span><small>{member.progress}%</small></button>)}</div><div className="admin-kpis"><div><span className="eyebrow">PATH COMPLETION</span><strong>41<span>%</span></strong><small>+8% this week</small></div><div className="gap-kpi"><div><span className="eyebrow">KNOWLEDGE GAPS</span><strong>07</strong><small className="amber-text">3 need review</small></div><button className="review-gaps-btn" onClick={onGapReview}>Review Gaps <ArrowUpRight size={13} /></button></div><div><span className="eyebrow">ACTIVE TODAY</span><strong>03</strong><small>of 4 members</small></div></div></section><section className="admin-command-deck"><div className="command-deck-intro"><span className="eyebrow seafoam">ADMIN COMMAND DECK / LIVE SIGNAL</span><h2>Turn team signals into the next useful move.</h2><p>Choose a signal to inspect the people, context, or knowledge gap behind it.</p></div><div className="admin-command-grid"><button className="admin-command-card command-heat" onClick={onHeatmap}><span className="command-card-icon"><BrainCircuit size={18} /></span><span><b>Knowledge coverage</b><strong>6 categories mapped</strong><small>Explore the team heatmap</small></span><ArrowUpRight size={16} /></button><button className="admin-command-card command-focus" onClick={onGapReview}><span className="command-card-icon"><Sparkles size={18} /></span><span><b>Next intervention</b><strong>Authentication needs context</strong><small>Review Bob’s unanswered questions</small></span><ArrowUpRight size={16} /></button><button className="admin-command-card command-pulse" onClick={() => onView("notes")}><span className="command-card-icon"><MessageSquare size={18} /></span><span><b>Latest team pulse</b><strong>Taylor shared an API update</strong><small>Open the Notes feed</small></span><ArrowUpRight size={16} /></button></div></section></div>;
}

function LearningPath'''
text, count = re.subn(admin_pattern, admin_replacement, text, count=1)
if count != 1:
    raise RuntimeError('AdminDashboard replacement failed')

# Replace Learning Path with a five-module map, per-module next action, and end-of-path assessment.
learning_pattern = r'function LearningPath\([\s\S]*?\n}\nfunction Documentation'
learning_replacement = '''function LearningPath({ onAssessmentSubmit, modulePlan, selectedModule, setSelectedModule, quizPassed, setQuizPassed, completedModules, setCompletedModules, quizAnswer, setQuizAnswer, showHint, setShowHint, onBobFeedback }: { onAssessmentSubmit: (answers: Record<number, string>) => void; modulePlan: ReturnType<typeof personalizeModules>; selectedModule: number; setSelectedModule: (value: number) => void; quizPassed: boolean; setQuizPassed: (value: boolean) => void; completedModules: number[]; setCompletedModules: React.Dispatch<React.SetStateAction<number[]>>; quizAnswer: string | null; setQuizAnswer: (value: string | null) => void; showHint: boolean; setShowHint: (value: boolean) => void; onBobFeedback: (value: "idle" | "wrong" | "correct") => void }) {
  const [started, setStarted] = useState(false); const [activeQuestion, setActiveQuestion] = useState(0); const [answers, setAnswers] = useState<Record<number, string | null>>({}); const [notes, setNotes] = useState(""); const [assessmentOpen, setAssessmentOpen] = useState(false); const [assessmentAnswers, setAssessmentAnswers] = useState<Record<number, string>>({});
  const mod = modulePlan[selectedModule] ?? modulePlan[0];
  const questionSets = [
    [{ prompt: "What does Atlas Core help a new developer understand first?", options: ["The project context", "Only the deployment pipeline", "A personal coding style", "The team calendar"], correct: "The project context" }, { prompt: "Which source should ground your first questions?", options: ["Repository and company docs", "A random tutorial", "A production secret", "A blank template"], correct: "Repository and company docs" }],
    [{ prompt: "Which command installs the project dependencies?", options: ["npm start", "pnpm install", "git pull", "node setup.js"], correct: "pnpm install" }, { prompt: "Where should local environment values live?", options: ["README.md", ".env.local", "package.json", "src/index.ts"], correct: ".env.local" }],
    [{ prompt: "What is the best way to trace a request through Atlas Core?", options: ["Follow the client-to-service boundary", "Read only the README title", "Change production data", "Skip the service layer"], correct: "Follow the client-to-service boundary" }, { prompt: "Why are boundaries useful during onboarding?", options: ["They reveal where context lives", "They hide all dependencies", "They remove the need for tests", "They replace documentation"], correct: "They reveal where context lives" }],
    [{ prompt: "What makes an API integration easier to reason about?", options: ["A clear contract", "Undocumented side effects", "Shared passwords", "Duplicated requests"], correct: "A clear contract" }, { prompt: "Where should a developer look for data ownership?", options: ["The service and persistence boundary", "Only the UI", "A screenshot", "The browser history"], correct: "The service and persistence boundary" }],
    [{ prompt: "What makes an authentication change safe to ship?", options: ["Clear session and data boundaries", "Skipping local checks", "Hardcoding tokens", "Removing the tests"], correct: "Clear session and data boundaries" }, { prompt: "What should you verify before a data change reaches the team?", options: ["Migration behavior and rollback", "Only the button color", "A random package", "The landing headline"], correct: "Migration behavior and rollback" }],
  ];
  const questions = questionSets[selectedModule] ?? questionSets[0]; const question = questions[activeQuestion];
  const triggerBob = (feedback: "wrong" | "correct") => { onBobFeedback("idle"); window.setTimeout(() => onBobFeedback(feedback), 20); };
  const resetModuleState = (index: number) => { setSelectedModule(index); setStarted(false); setAssessmentOpen(false); setActiveQuestion(0); setQuizAnswer(null); setShowHint(false); setAnswers({}); setQuizPassed(false); };
  const choose = (answer: string) => { setAnswers((current) => ({ ...current, [activeQuestion]: answer })); setQuizAnswer(answer); if (answer === question.correct) { triggerBob("correct"); if (activeQuestion === questions.length - 1) { setQuizPassed(true); setCompletedModules((current) => current.includes(selectedModule) ? current : [...current, selectedModule]); } else { window.setTimeout(() => { setActiveQuestion((current) => current + 1); setQuizAnswer(null); }, 500); } } else { setShowHint(false); triggerBob("wrong"); } };
  const completed = (index: number) => completedModules.includes(index) || modulePlan[index]?.status === "skipped";
  const locked = (index: number) => index > 0 && !completed(index - 1);
  const nextModule = selectedModule < modulePlan.length - 1 ? selectedModule + 1 : null;
  return <><div className="page-heading"><div><p className="eyebrow">ONBOARDING / {completedModules.length >= modulePlan.length - 1 ? "READY FOR ASSESSMENT" : "72% COMPLETE"}</p><h1>Learning path</h1><p>A visual route through the parts of Atlas Core that matter most to your role.</p></div><div className="progress-summary"><ProgressRing value={Math.min(100, Math.round((completedModules.length / modulePlan.length) * 100))} /><span><strong>{completedModules.length} of {modulePlan.length}</strong><small>modules mapped</small></span></div></div><div className={`learning-layout ${started ? "is-reading" : ""}`}><div className="module-map-panel"><div className="eyebrow">LEARNING MAP</div><p className="module-map-intro">A path that adapts to your signal.</p><div className="module-map">{modulePlan.map((item, index) => <button key={item.title} className={`module-map-node ${index === selectedModule ? "selected" : ""} ${completed(index) ? "complete" : ""} ${locked(index) ? "locked" : ""}`} onClick={() => { if (!locked(index)) resetModuleState(index); }}><span className="module-map-line" /><span className="module-num">{completed(index) ? <Check size={14} /> : locked(index) ? <LockKeyhole size={13} /> : item.tag}</span><span><strong>{item.title}</strong><small>{item.time} · {completed(index) ? "Complete" : locked(index) ? "Locked" : item.status === "skipped" ? "Shortened" : "Ready"}</small></span><ChevronRight size={15} /></button>)}</div>{completedModules.length >= modulePlan.length - 1 && <button className="assessment-map-cta" onClick={() => { setAssessmentOpen(true); setStarted(false); }}><BrainCircuit size={16} /><span><strong>Developer Twin assessment</strong><small>Five open-ended questions at the end of your path</small></span><ArrowUpRight size={14} /></button>}</div><section className={`module-detail ${started ? "reading-mode" : ""}`}>{assessmentOpen ? <AssessmentPanel answers={assessmentAnswers} setAnswers={setAssessmentAnswers} onSubmit={onAssessmentSubmit} /> : !started ? <><div className="module-detail-head"><div><span className="eyebrow seafoam">MODULE {mod.tag} / {completed(selectedModule) ? "COMPLETE" : "READY"}</span><h2>{mod.title}</h2><p>{mod.desc}</p></div><div className="module-time"><Zap size={15} /> {mod.time}</div></div><div className="module-progress"><span style={{ width: completed(selectedModule) ? "100%" : "62%" }} /></div><div className="module-summary"><span className="summary-mark"><BookOpen size={20} /></span><div><span className="eyebrow">MODULE SUMMARY</span><h3>{selectedModule === 1 ? "A calm first step into the codebase." : "Build the context you need."}</h3><p>{selectedModule === 1 ? "Learn the environment contract, the commands the team trusts, and how to verify a clean local session before touching product logic." : mod.desc}</p><div className="summary-meta"><span><Zap size={14} /> {mod.time}</span><span><CircleHelp size={14} /> 2 questions</span></div><div className="module-action-row"><button className="primary-cta" onClick={() => setStarted(true)}>{completed(selectedModule) ? "Review module" : "Start module"} <ArrowUpRight size={15} /></button>{completed(selectedModule) && nextModule !== null && <button className="secondary-cta" onClick={() => resetModuleState(nextModule)}>Next module <ArrowUpRight size={15} /></button>}</div></div></div></> : <div className="module-reading-wrap"><div className="module-reading"><div className="reading-toolbar"><button className="text-btn" onClick={() => setStarted(false)}><ChevronRight size={14} className="back-chevron" /> Return to Learning path</button><span className="eyebrow">MODULE {mod.tag} / READING MODE</span></div><div className="module-reading-head"><span className="eyebrow seafoam">ATLAS CORE / {mod.title.toUpperCase()}</span><h2>{mod.title}</h2><p>Make the next useful question smaller.</p></div><div className="reading-copy"><p className="lead">The fastest way into Atlas Core is to understand the context behind the product logic before you touch it.</p><p>{mod.desc} This module connects the repository shape to a working local session and gives you a practical way to verify what you now understand.</p><div className="command-block"><span>WORKING NOTES</span><code><i>$</i> trace the boundary<br /><i>$</i> verify the assumption</code></div><h3>Before you move on</h3><p>Keep the useful context close, then use the checkpoint below to confirm the two details that make this project predictable.</p></div><div className="quiz-card"><div className="quiz-title"><span className="eyebrow">CHECKPOINT / 0{activeQuestion + 1} OF 02</span><h3>{question.prompt}</h3></div><div className="quiz-options">{question.options.map((answer) => <button key={answer} className={answers[activeQuestion] === answer ? answer === question.correct ? "correct" : "wrong" : ""} onClick={() => choose(answer)}>{answer}<span>{answers[activeQuestion] === answer && (answer === question.correct ? <Check size={15} /> : "×")}</span></button>)}</div></div>{quizPassed && nextModule !== null && <div className="module-next-action"><span><strong>Module complete.</strong><small>The next module is ready when you are.</small></span><button className="secondary-cta" onClick={() => resetModuleState(nextModule)}>Next module <ArrowUpRight size={15} /></button></div>}{quizPassed && nextModule === null && <div className="module-next-action assessment-ready"><span><strong>Path complete.</strong><small>Your five-question Developer Twin assessment is ready.</small></span><button className="secondary-cta" onClick={() => { setAssessmentOpen(true); setStarted(false); }}>Open assessment <BrainCircuit size={15} /></button></div>}<aside className="module-notes"><div className="section-head"><div><span className="eyebrow">PRIVATE NOTES</span><h3>Keep a thought here.</h3></div><MoreHorizontal size={17} /></div><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Write anything you want to remember..." /><span className="notes-hint">Saved locally in this demo</span></aside></div>}</section></div></>;
}

function AssessmentPanel({ answers, setAnswers, onSubmit }: { answers: Record<number, string>; setAnswers: React.Dispatch<React.SetStateAction<Record<number, string>>>; onSubmit: (answers: Record<number, string>) => void }) { const complete = Object.keys(answers).length === 5 && Object.values(answers).every((answer) => answer.trim().length > 0); return <div className="assessment-shell"><div className="assessment-intro"><span className="eyebrow seafoam">BOB’S OPEN-ENDED READ / 05 QUESTIONS</span><h2>Show your thinking, not your memorization.</h2><p>Answer exactly five descriptive prompts in your own words. Bob will use the responses to update your Developer Twin after the final module.</p><div className="assessment-status"><span><BrainCircuit size={15} /> {Object.keys(answers).length} of 5 answered</span><span>Private to your Twin</span></div></div><div className="assessment-list">{["Describe how a request moves through Atlas Core from the client to the service layer.", "If an API response is unexpectedly slow, what would you inspect first and why?", "Explain how you would keep authentication context safe across a local development flow.", "What makes a database change safe to ship in a team-owned product?", "When you are stuck in an unfamiliar repository, how do you decide what to learn next?"].map((question, index) => <label className="assessment-question" key={question}><span><b>0{index + 1}</b>{question}</span><textarea value={answers[index] ?? ""} onChange={(event) => setAnswers((current) => ({ ...current, [index]: event.target.value }))} placeholder="Write a short explanation..." /></label>)}<div className="assessment-actions"><button className="primary-cta" disabled={!complete} onClick={() => onSubmit(answers)}>{complete ? "Analyze with Bob" : `Answer ${5 - Object.keys(answers).length} more`} <ArrowUpRight size={15} /></button></div></div></div>; }

function Documentation'''
text, count = re.subn(learning_pattern, learning_replacement, text, count=1)
if count != 1:
    raise RuntimeError('LearningPath replacement failed')

# Remove the Documentation plus control.
text = text.replace('<div className="tree-head"><span>ATLAS CORE</span><button><Plus size={15} /></button></div>', '<div className="tree-head"><span>ATLAS CORE</span></div>')

# Replace NotesFeed so Taylor is the admin author and the role badge is not an extra overlay.
notes_pattern = r'function NotesFeed\(\)[\s\S]*?\nfunction Repository'
notes_replacement = '''function NotesFeed() { return <><div className="page-heading"><div><p className="eyebrow">TEAM COMMUNICATION / LIVE</p><h1>Notes feed</h1><p>Questions, updates, and small signals from the people building Atlas Core.</p></div><button className="subtle-btn"><Users size={16} /> 4 members online</button></div><div className="notes-shell"><div className="notes-stream"><div className="stream-day">TODAY · THURSDAY</div>{[{initials:"TS",color:"#f3b56b",name:"Taylor Swift",role:"Team admin",time:"09:42",text:"The API glossary is ready for review. I added the auth edge cases Bob was missing."},{initials:"MC",color:"#8cf7d0",name:"Maya Chen",role:"Frontend engineer",time:"10:06",text:"Perfect — I’m moving through Local Setup now. The checkpoint is clear."},{initials:"AS",color:"#9eaaff",name:"Aarav Shah",role:"Backend engineer",time:"10:31",text:"Architecture module unlocked on my side. The request flow diagram helped a lot."}].map((note) => <div className={`feed-note ${note.role === "Team admin" ? "admin-note" : ""}`} key={note.time}><Avatar initials={note.initials} color={note.color} /><div><div className="feed-meta"><strong>{note.name}</strong><span>{note.role}</span><time>{note.time}</time></div><p>{note.text}</p></div></div>)}</div><div className="composer-panel"><span className="eyebrow">NEW NOTE</span><textarea placeholder="Share an update with the team..." /><div><span>⌘ ↵ to send</span><button className="primary-cta" onClick={() => toast.success("Note ready to send once the API is connected.")}>Post note <ArrowUpRight size={15} /></button></div></div></div></>; }

function Repository'''
text, count = re.subn(notes_pattern, notes_replacement, text, count=1)
if count != 1:
    raise RuntimeError('NotesFeed replacement failed')

# Update the dashboard Notes preview and project-team copy to Taylor.
text = text.replace('<Avatar initials="MC" color="#8cf7d0" /><p><strong>Maya Chen</strong><span>“API glossary is ready for review.”', '<Avatar initials="TS" color="#f3b56b" /><p><strong>Taylor Swift</strong><span>“API glossary is ready for review.”')
text = text.replace('with Maya Chen coordinating the admin workspace', 'with Taylor Swift coordinating the admin workspace')

# Remove profile overflow ellipses and add the new gap review page before ProjectModal.
text = text.replace('<MoreHorizontal size={16} /></div></div>\n    </aside>', '</div></div>\n    </aside>')
gap_component = '''\nfunction KnowledgeGapReview({ onBack }: { onBack: () => void }) { const [uploaded, setUploaded] = useState(false); return <div className="gap-review-page"><div className="page-heading"><div><p className="eyebrow amber-text">ADMIN / KNOWLEDGE GAPS</p><h1>Review Gaps</h1><p>See the questions Bob could not answer confidently, then add the context that closes the loop.</p></div><button className="text-btn" onClick={onBack}>Dashboard <ArrowUpRight size={14} /></button></div><div className="gap-review-layout"><section className="gap-review-list"><div className="gap-review-head"><div><span className="eyebrow">UNANSWERED SIGNALS</span><h2>Questions that need better context.</h2></div><span className="gap-count">03 open</span></div>{[{developer:"Maya Chen",question:"Where does authentication context get refreshed between the client and service layer?",response:"I can trace the session token into the request, but the repository map does not show the refresh boundary clearly yet."},{developer:"Sofia Rossi",question:"Which service owns the persistence rules for a new onboarding module?",response:"Bob found references across the API and database layers, but not enough company documentation to name a single owner."},{developer:"Noah Williams",question:"What is the expected rollback path for a schema change?",response:"The migration files are visible, but the team’s rollback convention is not documented in the current context set."}].map((item) => <article className="gap-question" key={item.developer}><div className="gap-question-meta"><Avatar initials={item.developer.split(" ").map((part) => part[0]).join("")} color="#f3b56b" /><span><strong>{item.developer}</strong><small>Open-ended assessment</small></span></div><div className="gap-question-copy"><span className="eyebrow">DEVELOPER QUESTION</span><p>“{item.question}”</p><div className="bob-response"><span className="eyebrow">BOB’S RESPONSE</span><p>{item.response}</p></div></div></article>)}</section><aside className="gap-upload-card"><div className="gap-upload-orb"><Upload size={20} /></div><span className="eyebrow">CLOSE THE GAP</span><h2>Add context for Bob.</h2><p>Upload an architecture note, auth guide, or team decision record. The Knowledge Engine will use it to re-run the affected read.</p><label className={`gap-upload-drop ${uploaded ? "uploaded" : ""}`}><input type="file" accept=".pdf,.doc,.docx,.md,.txt" onChange={() => setUploaded(true)} /><strong>{uploaded ? "Context file staged" : "Upload documentation"}</strong><small>{uploaded ? "Ready for the next indexing pass" : "PDF, DOCX, Markdown, or TXT"}</small></label><button className="primary-cta" onClick={() => toast.success(uploaded ? "Documentation queued for Bob’s next analysis." : "Choose a documentation file first.")}>{uploaded ? "Queue re-analysis" : "Choose a file"} <ArrowUpRight size={15} /></button></aside></div></div>; }\n\n'''
text = text.replace('\nfunction ProjectModal', gap_component + 'function ProjectModal')

home_path.write_text(text)
print('ux pass source rewrite applied')
''
